'use strict';
// Metin Stones: sculpted, rigged stone models drawn by the engine's hero path (GL.drawHero), one design per biome
// (generated by scripts/boss-forge/metin.js into assets/metin). Purely visual: the damage stage comes from the hp the
// server already replicates (so every client shows the same stage), the summon and destruction effects from the
// 'fx'/'summon' and 'die' events every client already receives. Until a model has loaded, or where the hero renderer is
// unavailable, the primitive stone (stoneModel) is drawn exactly as before.
(function () {
  const DESIGNS = {
    meadows: { types: ['stone'], rim: [.06, .14, .05], glow: [.42, 1, .48], leaf: [.3, .62, .18], dust: [.45, .44, .38], fall: 60 },  // leaves drift down
    ember: { types: ['emberstone'], rim: [.18, .05, .01], glow: [1, .5, .12], leaf: [1, .72, .25], dust: [.22, .2, .19], fall: -90 }, // embers and smoke rise
    gloom: { types: ['jadestone'], rim: [.1, .04, .14], glow: [.55, 1, .3], leaf: [.7, .35, 1], dust: [.25, .2, .28], fall: -25 },  // drifting spores
    war: { types: ['bonestone'], rim: [.16, .03, .02], glow: [1, .14, .1], leaf: [1, .65, .3], dust: [.3, .27, .25], fall: 200 },     // sparks and grit
    void: { types: ['voidstone'], rim: [.14, .04, .2], glow: [.95, .3, 1], leaf: [.6, .35, 1], dust: [.12, .08, .16], fall: -40 },     // drifting void shards
    ossuary: { types: [], rim: [.05, .12, .08], glow: [.55, 1, .7], leaf: [.75, 1, .85], dust: [.55, .53, .45], fall: -60 },         // rising souls (Necropolis Bone Pillars)
    doom: { types: ['doomstone'], rim: [.04, .12, .1], glow: [.35, 1, .6], leaf: [.55, .85, 1], dust: [.1, .1, .12], fall: -70 },    // dark souls and spectral mist
    frost: { types: ['froststone'], rim: [.06, .12, .2], glow: [.5, .9, 1], leaf: [.88, .96, 1], dust: [.82, .9, .98], fall: 25 },    // snow and freezing mist
  };
  const BY_TYPE = {}; for (const [id, d] of Object.entries(DESIGNS)) for (const ty of d.types) BY_TYPE[ty] = id;
  const STAGE_CLIP = [null, 'Intact', 'Damaged', 'Near'];
  const MODELS = new Map(); // id -> { md, far } | 'loading' | 'failed'
  const seen = new Map(); // mob id -> { x, z, id, t } (where each stone was last drawn, for its summon effect)
  const ghosts = []; // destroyed stones playing their Break clip
  let pace = 1; // break playback speed (1 in play; screenshots of the sequence slow it down)
  const ok = () => typeof GL !== 'undefined' && GL.heroOK && GL.heroOK() && GL.pose;

  function modelFor(id) {
    const have = MODELS.get(id); if (have !== undefined) return typeof have === 'object' ? have : null;
    if (!ok()) { MODELS.set(id, 'failed'); return null; }
    MODELS.set(id, 'loading');
    Promise.all([GL.loadGLB('assets/metin/' + id + '.glb'), GL.loadGLB('assets/metin/' + id + '-far.glb').catch(() => null)])
      .then(([md, far]) => MODELS.set(id, { md, far })).catch(err => { console.warn('Metin Stone model ' + id + ' not loaded', err); MODELS.set(id, 'failed'); });
    return null;
  }
  // which design a stone type shows (a biome can override a shared type, e.g. Necropolis vs Warfields)
  // Bone Pillars standing in Necropolis scenery (look 6) show the Ossuary Pillar; elsewhere the Bloodforged Stone
  function designOf(ty, x, z) { const id = BY_TYPE[ty] || null; if (id === 'war' && x !== undefined && typeof lookZoneOf === 'function' && lookZoneOf(x, z) === 6) return 'ossuary'; return id; }
  // 1 intact (above 2/3 health), 2 damaged, 3 near destruction (below 1/3)
  const stageOf = (hp, mh) => { const f = mh > 0 ? hp / mh : 1; return f > 2 / 3 ? 1 : f > 1 / 3 ? 2 : 3; };
  const yawOf = id => ((id || 0) * 2.39996) % (Math.PI * 2);
  const nodesFor = (e, md) => (e.mNodes && e.mNodes.length === md.N * 16 ? e.mNodes : (e.mNodes = new Float32Array(md.N * 16)));
  const far = (x, z) => typeof cam !== 'undefined' && Math.hypot(x - cam.x, z - cam.z) > 640;

  // draw one living stone; false = not premium or not loaded (the caller draws the primitive stone)
  function draw(e, t, m) {
    const id = designOf(m.ty, e.rx, e.ry); if (!id) return false; const hm = modelFor(id); if (!hm) return false;
    const now = performance.now(), md = hm.md, d = DESIGNS[id], st = stageOf(m.hp, m.mh);
    const S = e.mst || (e.mst = { stage: st, prev: st, at: -1e9 });
    if (st !== S.stage) { S.prev = S.stage; S.stage = st; S.at = now; if (st > S.prev) crumble(e.rx, e.ry, d, st); }
    const time = now / 1000 % 4, w = Math.min(1, (now - S.at) / 700), nodes = nodesFor(e, md);
    GL.pose(md, STAGE_CLIP[S.stage], time, STAGE_CLIP[S.prev], time, w, nodes);
    const isFar = hm.far && far(e.rx, e.ry);
    GL.drawHero(isFar ? hm.far : md, nodes, e.rx, 0, e.ry, yawOf(m.id), 1, { rim: d.rim, emc: e.flash > now - 110 ? [.35, .35, .35] : null, shadow: hm.far || undefined });
    ambient(e.rx, e.ry, d, st, now, isFar);
    seen.set(m.id, { x: e.rx, z: e.ry, id, t: now });
    return true;
  }
  // a faint rune circle on the ground and drifting motes; more, and faster, as the stone breaks up
  function ambient(x, z, d, st, now, isFar) {
    if (typeof D !== 'function') return;
    D(M.ring, x, 1.2, z, 40, 1, 40, now / 2500, 0, d.glow, 1, .22 + st * .06);
    if (isFar || typeof burst !== 'function') return;
    if (Math.random() < .05 * st) { const a = Math.random() * 6.283, r = 10 + Math.random() * 18; burst(x + Math.cos(a) * r, 8 + Math.random() * 50, z + Math.sin(a) * r, 1, d.glow, 10, 2.2, 1.1, 1, -18); }
    if (st >= 3 && Math.random() < .25) burst(x + (Math.random() - .5) * 8, 40, z + 6, 1, d.glow, 40, .7, 1.4, 1, -30);
  }
  // pieces breaking off when the stone drops a stage
  function crumble(x, z, d, st) {
    if (typeof burst !== 'function') return;
    burst(x, 40, z, 16 + st * 6, d.dust, 70, 1.1, 2.2, 0, 260); burst(x, 40, z + 6, 12, d.glow, 90, .8, 1.6, 1, 120);
    if (typeof addRing === 'function') addRing(x, z, 10, 46, d.glow, 450, 3, .6);
  }

  // a wave of guardians: roots of green light surge out of the ground in a ring, leaves whirl up
  function summon(x, z) {
    let best = null, bd = 30; for (const s of seen.values()) { const dd = Math.hypot(s.x - x, s.z - z); if (dd < bd && performance.now() - s.t < 3000) { bd = dd; best = s; } }
    if (!best || typeof burst !== 'function') return false; const d = DESIGNS[best.id];
    if (typeof addRing === 'function') { addRing(x, z, 20, 150, d.glow, 900, 2, .8); addRing(x, z, 10, 90, d.leaf, 700, 3, .5); }
    for (let i = 0; i < 10; i++) { const a = i / 10 * 6.283, r = 60 + (i % 3) * 30, px = x + Math.cos(a) * r, pz = z + Math.sin(a) * r;
      burst(px, 2, pz, 5, d.glow, 50, 1, 1.8, 1, -90); burst(px, 4, pz, 4, d.leaf, 60, 1.4, 1.6, .2, d.fall); }
    burst(x, 45, z, 26, d.glow, 120, 1, 2, 1, -40);
    if (typeof sfx === 'function') sfx('boss', x, z);
    return true;
  }
  // destroyed: the core flares, the cracks blaze, the stone flies apart and sinks; a burst of green light and leaves
  function shatter(x, z, ty) {
    const id = designOf(ty, x, z), hm = id && modelFor(id); if (!hm) return false; const d = DESIGNS[id];
    let yaw = 0; for (const [mid, s] of seen) if (Math.hypot(s.x - x, s.z - z) < 30) { yaw = yawOf(mid); seen.delete(mid); break; }
    ghosts.push({ md: hm.md, x, z, yaw, t0: performance.now(), d, nodes: new Float32Array(hm.md.N * 16), boomed: false });
    if (typeof burst === 'function') burst(x, 40, z, 30, d.glow, 60, .5, 2.4, 1, -20);
    if (typeof sfx === 'function') sfx('boss', x, z);
    return true;
  }
  // per frame: destroyed stones play out their Break clip, then vanish in dust
  function frame() {
    const now = performance.now();
    for (let i = ghosts.length - 1; i >= 0; i--) {
      const g = ghosts[i], s = (now - g.t0) / 1000 * pace; if (s > 1.8) { ghosts.splice(i, 1); continue; }
      if (!g.boomed && s > .35 && typeof burst === 'function') { g.boomed = true; const d = g.d;
        burst(g.x, 40, g.z, 90, d.glow, 260, 1.2, 2.6, 1, 120); burst(g.x, 30, g.z, 50, d.dust, 180, 1.4, 3.2, 0, 300); burst(g.x, 50, g.z, 40, d.leaf, 150, 2, 1.8, .2, d.fall * 1.5);
        if (typeof addRing === 'function') { addRing(g.x, g.z, 10, 160, d.glow, 700, 3, 1); addRing(g.x, g.z, 6, 90, [1, 1, 1], 400, 5, 1); } }
      GL.pose(g.md, 'Break', s, null, 0, 1, g.nodes);
      GL.drawHero(g.md, g.nodes, g.x, 0, g.z, g.yaw, 1, { rim: g.d.rim, emc: s < .35 ? [s, s, s] : null });
    }
    if (seen.size > 200) for (const [k, s] of seen) if (now - s.t > 10000) seen.delete(k);
  }
  window.MetinStones = { DESIGNS, draw, summon, shatter, frame, stageOf, designOf, active: () => ghosts.length, _model: id => MODELS.get(id), pace: k => { pace = k > 0 ? k : 1; } };
})();
